const int FONT_CH_SYMBOLS_SIZE = 435;


const uint8_t* font_get_glyph(uint16_t unicode) {
    for (int i = 0; i < FONT_CH_SYMBOLS_SIZE; i++) {
        if (FONT_CH_SYMBOLS[i].unicode == unicode) {
            return FONT_CH_SYMBOLS[i].bitmap;
        }
    }

    int left = 0;
    int right = FONT_GB2312_SIZE - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (FONT_GB2312[mid].unicode == unicode) {
            return FONT_GB2312[mid].bitmap;
        }
        if (FONT_GB2312[mid].unicode < unicode) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return NULL;
}
